 INSERT INTO ledger_private.trivia_attempts(player,game,day,slot,version) VALUES(p->>'player',p->>'game',d,s,v) ON CONFLICT(player,game,day) DO NOTHING;
INSERT INTO ledger_private.trivia_packs VALUES ('odd-one-out',0,2,'[{"kind":"choice","tag":"Winter wardrobe","prompt":"Find the outsider.","options":["Cashmere","Wool","Silk","Linen"],"answer":"Linen","explanation":"Three fibres come from animals. Linen comes from flax.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-51","version":2},{"kind":"choice","tag":"Around a circle","prompt":"Find the outsider.","options":["Circumference","Diameter","Radius","Hypotenuse"],"answer":"Hypotenuse","explanation":"Three describe measurements of a circle. A hypotenuse is a side of a right triangle.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-85","version":2},{"kind":"choice","tag":"The camera bag","prompt":"Find the outsider.","options":["ISO","Kerning","Aperture","Shutter speed"],"answer":"Kerning","explanation":"Three are photographic exposure settings. Kerning adjusts spacing between letters.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-89","version":2},{"kind":"choice","tag":"Wind instruments","prompt":"Find the outsider.","options":["Flute","Recorder","Piccolo","Violin"],"answer":"Violin","explanation":"Three produce their sound from an air column. A violin uses vibrating strings.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-44","version":2},{"kind":"choice","tag":"Botany","prompt":"Find the outsider.","options":["Strawberry","Banana","Grape","Tomato"],"answer":"Strawberry","explanation":"Three are botanical berries. A strawberry is an aggregate accessory fruit.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-1","version":2}]'::jsonb);
INSERT INTO ledger_private.trivia_packs VALUES ('odd-one-out',1,2,'[{"kind":"choice","tag":"Landforms","prompt":"Find the outsider.","options":["Estuary","Delta","Caldera","Meander"],"answer":"Caldera","explanation":"Three relate to rivers. A caldera is a large volcanic depression.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-40","version":2},{"kind":"choice","tag":"Seasoning","prompt":"Find the outsider.","options":["Clove","Capers","Cumin","Saffron"],"answer":"Cumin","explanation":"Three come from flower parts or buds. Cumin is used for its dried fruits, commonly called seeds.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-71","version":2},{"kind":"choice","tag":"Across the table","prompt":"Find the outsider.","options":["Fork","Whisk","Spoon","Chopsticks"],"answer":"Whisk","explanation":"Three take food to your mouth. A whisk mixes ingredients.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-32","version":2},{"kind":"choice","tag":"Garden visitors","prompt":"Find the outsider.","options":["Dragonfly","Bee","Ant","Wasp"],"answer":"Dragonfly","explanation":"Three belong to the insect order Hymenoptera. Dragonflies belong to Odonata.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-88","version":2},{"kind":"choice","tag":"Moving water","prompt":"Find the outsider.","options":["Mediterranean","Pacific","Atlantic","Indian"],"answer":"Mediterranean","explanation":"Three are named oceans. The Mediterranean is a sea.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-79","version":2}]'::jsonb);
INSERT INTO ledger_private.trivia_packs VALUES ('odd-one-out',2,2,'[{"kind":"choice","tag":"Japanese food","prompt":"Find the outsider.","options":["Soba","Udon","Mochi","Ramen"],"answer":"Mochi","explanation":"Three are noodles. Mochi is a rice cake.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-49","version":2},{"kind":"choice","tag":"More rocks","prompt":"Find the outsider.","options":["Limestone","Sandstone","Gneiss","Shale"],"answer":"Gneiss","explanation":"Three are sedimentary rocks. Gneiss is metamorphic.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-29","version":2},{"kind":"choice","tag":"Geometric angles","prompt":"Find the outsider.","options":["Obtuse","Reflex","Isosceles","Acute"],"answer":"Isosceles","explanation":"Three describe angles. Isosceles describes a triangle with two equal sides.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-84","version":2},{"kind":"choice","tag":"Pasta shapes","prompt":"Find the outsider.","options":["Fusilli","Penne","Polenta","Farfalle"],"answer":"Polenta","explanation":"Three are pasta shapes. Polenta is made from ground maize.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-48","version":2},{"kind":"choice","tag":"Table salt","prompt":"Find the outsider.","options":["Lithium","Potassium","Calcium","Sodium"],"answer":"Calcium","explanation":"Three are alkali metals in group 1. Calcium is in group 2.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-75","version":2}]'::jsonb);
INSERT INTO ledger_private.trivia_packs VALUES ('odd-one-out',3,2,'[{"kind":"choice","tag":"On a bicycle","prompt":"Find the outsider.","options":["Chainring","Crank","Pedal","Keel"],"answer":"Keel","explanation":"Three are bicycle drivetrain parts. A keel belongs to a boat.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-83","version":2},{"kind":"choice","tag":"Punctuation","prompt":"Find the outsider.","options":["Semicolon","Comma","Colon","Paragraph"],"answer":"Paragraph","explanation":"Three are punctuation marks. A paragraph is a unit of text.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-42","version":2},{"kind":"choice","tag":"Beyond the clouds","prompt":"Find the outsider.","options":["Gemini","Mercury","Apollo","Hubble"],"answer":"Hubble","explanation":"Three were US crewed spaceflight programmes. Hubble is a space telescope.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-57","version":2},{"kind":"choice","tag":"Making a print","prompt":"Find the outsider.","options":["Woodcut","Origami","Lithography","Etching"],"answer":"Origami","explanation":"Three are printmaking techniques. Origami folds paper.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-64","version":2},{"kind":"choice","tag":"Geometric solids","prompt":"Find the outsider.","options":["Cube","Tetrahedron","Octahedron","Cylinder"],"answer":"Cylinder","explanation":"Three are polyhedra with flat polygonal faces. A cylinder has a curved surface.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-12","version":2}]'::jsonb);
INSERT INTO ledger_private.trivia_packs VALUES ('odd-one-out',4,2,'[{"kind":"choice","tag":"In a flower","prompt":"Find the outsider.","options":["Petal","Stamen","Frond","Sepal"],"answer":"Frond","explanation":"Three are flower structures. A frond is a leaf, especially of a fern or palm.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-36","version":2},{"kind":"choice","tag":"Word endings","prompt":"Find the outsider.","options":["Careless","Fearless","Unless","Hopeless"],"answer":"Unless","explanation":"Three use -less to mean without something. Unless is a conjunction, not that suffix construction.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-38","version":2},{"kind":"choice","tag":"Making a picture","prompt":"Find the outsider.","options":["Gouache","Oil paint","Charcoal","Watercolour"],"answer":"Charcoal","explanation":"Three are paints with a binder and pigment. Charcoal is a dry drawing medium.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-63","version":2},{"kind":"choice","tag":"Coffee counter","prompt":"Find the outsider.","options":["Espresso","Lungo","Matcha","Ristretto"],"answer":"Matcha","explanation":"Three are coffee preparations. Matcha is powdered green tea.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-10","version":2},{"kind":"choice","tag":"Birds","prompt":"Find the outsider.","options":["Ostrich","Emu","Albatross","Kiwi"],"answer":"Albatross","explanation":"Three are flightless birds. An albatross can soar over oceans.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-15","version":2}]'::jsonb);
INSERT INTO ledger_private.trivia_packs VALUES ('odd-one-out',5,2,'[{"kind":"choice","tag":"More mammals","prompt":"Find the outsider.","options":["Echidna","Wombat","Platypus","Long-beaked echidna"],"answer":"Wombat","explanation":"Three are egg-laying monotremes. A wombat is a marsupial.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-81","version":2},{"kind":"choice","tag":"Calendar","prompt":"Find the outsider.","options":["Monday","Thursday","Sunday","Solstice"],"answer":"Solstice","explanation":"Three are weekdays. A solstice is an astronomical event.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-73","version":2},{"kind":"choice","tag":"At the keyboard","prompt":"Find the outsider.","options":["Pixel","Alt","Ctrl","Shift"],"answer":"Pixel","explanation":"Three are modifier keys. A pixel is a picture element.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-9","version":2},{"kind":"choice","tag":"The bookshelf","prompt":"Find the outsider.","options":["Interval","Preface","Appendix","Index"],"answer":"Interval","explanation":"Three can be sections of a book. An interval is a gap or pause.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-25","version":2},{"kind":"choice","tag":"Chessboard","prompt":"Find the outsider.","options":["Knight","Bishop","Queen","Rook"],"answer":"Knight","explanation":"Three travel along straight lines on the board. A knight jumps in an L shape.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-17","version":2}]'::jsonb);
INSERT INTO ledger_private.trivia_packs VALUES ('odd-one-out',6,2,'[{"kind":"choice","tag":"Map room","prompt":"Find the outsider.","options":["Longitude","Equator","Latitude","Altitude"],"answer":"Altitude","explanation":"Three concern horizontal position on Earth. Altitude describes height.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-23","version":2},{"kind":"choice","tag":"On the screen","prompt":"Find the outsider.","options":["JavaScript","HTML","Bluetooth","CSS"],"answer":"Bluetooth","explanation":"Three are core web page technologies. Bluetooth is a wireless communication technology.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-55","version":2},{"kind":"choice","tag":"In the sky","prompt":"Find the outsider.","options":["Andromeda Galaxy","Vega","Sirius","Polaris"],"answer":"Andromeda Galaxy","explanation":"Three are individual stars. The Andromeda Galaxy contains many stars.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-76","version":2},{"kind":"choice","tag":"Electric circuits","prompt":"Find the outsider.","options":["Volt","Ampere","Pascal","Ohm"],"answer":"Pascal","explanation":"Three are units used for electrical quantities. The pascal measures pressure.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-66","version":2},{"kind":"choice","tag":"At the piano","prompt":"Find the outsider.","options":["D major","Allegro","G major","C major"],"answer":"Allegro","explanation":"Three name musical keys. Allegro is a tempo indication.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-22","version":2}]'::jsonb);
INSERT INTO ledger_private.trivia_packs VALUES ('odd-one-out',7,2,'[{"kind":"choice","tag":"Materials","prompt":"Find the outsider.","options":["Brass","Silver","Copper","Gold"],"answer":"Brass","explanation":"Three are chemical elements. Brass is an alloy, mainly copper and zinc.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-4","version":2},{"kind":"choice","tag":"Around the house","prompt":"Find the outsider.","options":["Doorknob","Gutter","Latch","Hinge"],"answer":"Gutter","explanation":"Three are commonly parts of a door. A gutter channels rainwater from a roof.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-82","version":2},{"kind":"choice","tag":"Language","prompt":"Find the outsider.","options":["Noun","Adjective","Syllable","Verb"],"answer":"Syllable","explanation":"Three are parts of speech. A syllable is a unit of pronunciation.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-61","version":2},{"kind":"choice","tag":"Adding light","prompt":"Find the outsider.","options":["Green","Blue","Yellow","Red"],"answer":"Yellow","explanation":"Red, green and blue are the additive primaries used by an RGB display.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-31","version":2},{"kind":"choice","tag":"Under the microscope","prompt":"Find the outsider.","options":["Ant","Butterfly","Beetle","Spider"],"answer":"Spider","explanation":"Three are insects, with six legs as adults. Spiders are arachnids with eight legs.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-19","version":2}]'::jsonb);
INSERT INTO ledger_private.trivia_packs VALUES ('odd-one-out',8,2,'[{"kind":"choice","tag":"Underfoot","prompt":"Find the outsider.","options":["Granite","Marble","Basalt","Obsidian"],"answer":"Marble","explanation":"Three form from molten rock. Marble forms when limestone or dolostone is metamorphosed.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-28","version":2},{"kind":"choice","tag":"A matter of light","prompt":"Find the outsider.","options":["Sound","Radio","X-ray","Microwave"],"answer":"Sound","explanation":"Three are electromagnetic waves. Sound is a mechanical vibration in a medium.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-14","version":2},{"kind":"choice","tag":"In the kitchen","prompt":"Find the outsider.","options":["Cinnamon","Mint","Basil","Rosemary"],"answer":"Cinnamon","explanation":"Three seasonings use leaves. Cinnamon comes from bark.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-16","version":2},{"kind":"choice","tag":"In a story","prompt":"Find the outsider.","options":["Simile","Footnote","Personification","Metaphor"],"answer":"Footnote","explanation":"Three are figures of speech. A footnote is an annotation.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-78","version":2},{"kind":"choice","tag":"A science shelf","prompt":"Find the outsider.","options":["Geology","Calligraphy","Astronomy","Botany"],"answer":"Calligraphy","explanation":"Three are natural sciences. Calligraphy is the art of beautiful writing.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-77","version":2}]'::jsonb);
INSERT INTO ledger_private.trivia_packs VALUES ('odd-one-out',9,2,'[{"kind":"choice","tag":"Building blocks","prompt":"Find the outsider.","options":["Electron","Neutron","Proton","Photon"],"answer":"Photon","explanation":"Three are the usual constituents of an atom. A photon is a quantum of electromagnetic radiation.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-53","version":2},{"kind":"choice","tag":"In a cell","prompt":"Find the outsider.","options":["Mitochondrion","Nucleus","Ribosome","Tibia"],"answer":"Tibia","explanation":"Three are cellular structures. The tibia is a bone.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-58","version":2},{"kind":"choice","tag":"The colour wheel","prompt":"Find the outsider.","options":["Magenta","Yellow","Cyan","Green"],"answer":"Green","explanation":"Cyan, magenta and yellow are subtractive colour primaries. Green is not one of those three.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-30","version":2},{"kind":"choice","tag":"At the bakery","prompt":"Find the outsider.","options":["Focaccia","Risotto","Baguette","Ciabatta"],"answer":"Risotto","explanation":"Three are breads. Risotto is a rice dish.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-47","version":2},{"kind":"choice","tag":"Sweet things","prompt":"Find the outsider.","options":["Molasses","Maple syrup","Vinegar","Honey"],"answer":"Vinegar","explanation":"Three are sweeteners. Vinegar is an acidic product of fermentation.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-27","version":2}]'::jsonb);
INSERT INTO ledger_private.trivia_packs VALUES ('odd-one-out',10,2,'[{"kind":"choice","tag":"Strings attached","prompt":"Find the outsider.","options":["Harp","Guitar","Timpani","Violin"],"answer":"Timpani","explanation":"Three are string instruments. Timpani are drums.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-45","version":2},{"kind":"choice","tag":"Shapes on paper","prompt":"Find the outsider.","options":["Rectangle","Triangle","Sphere","Pentagon"],"answer":"Sphere","explanation":"Three are flat polygons. A sphere is a three-dimensional surface.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-62","version":2},{"kind":"choice","tag":"The solar system","prompt":"Find the outsider.","options":["Jupiter","Saturn","Mars","Neptune"],"answer":"Mars","explanation":"Three have ring systems. Mars has no known rings.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-37","version":2},{"kind":"choice","tag":"In a deck","prompt":"Find the outsider.","options":["Clubs","Hearts","Spades","Crowns"],"answer":"Crowns","explanation":"Three are suits in a standard French-suited deck. Crowns is not.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-24","version":2},{"kind":"choice","tag":"Navigation","prompt":"Find the outsider.","options":["Sextant","GPS receiver","Compass","Thermometer"],"answer":"Thermometer","explanation":"Three help determine direction or position. A thermometer measures temperature.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-35","version":2}]'::jsonb);
INSERT INTO ledger_private.trivia_packs VALUES ('odd-one-out',11,2,'[{"kind":"choice","tag":"In the freezer","prompt":"Find the outsider.","options":["Condensation","Freezing","Evaporation","Deposition"],"answer":"Evaporation","explanation":"Three release latent heat to their surroundings. Evaporation absorbs it.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-46","version":2},{"kind":"choice","tag":"In the forest","prompt":"Find the outsider.","options":["Fern","Oak","Birch","Beech"],"answer":"Fern","explanation":"Three are flowering trees. Ferns reproduce by spores rather than seeds.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-70","version":2},{"kind":"choice","tag":"Timekeeping","prompt":"Find the outsider.","options":["Hourglass","Barometer","Pendulum clock","Sundial"],"answer":"Barometer","explanation":"Three measure time. A barometer measures atmospheric pressure.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-34","version":2},{"kind":"choice","tag":"Human skeleton","prompt":"Find the outsider.","options":["Tibia","Femur","Humerus","Aorta"],"answer":"Aorta","explanation":"Three are bones. The aorta is an artery.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-59","version":2},{"kind":"choice","tag":"In the garden","prompt":"Find the outsider.","options":["Turnip","Carrot","Potato","Radish"],"answer":"Potato","explanation":"Three are harvested for roots. A potato is a stem tuber.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-13","version":2}]'::jsonb);
INSERT INTO ledger_private.trivia_packs VALUES ('odd-one-out',12,2,'[{"kind":"choice","tag":"Fairground physics","prompt":"Find the outsider.","options":["Pulley","Battery","Inclined plane","Lever"],"answer":"Battery","explanation":"Three are classical simple machines. A battery stores chemical energy.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-41","version":2},{"kind":"choice","tag":"Sound and motion","prompt":"Find the outsider.","options":["Hertz","Pitch","Luminance","Frequency"],"answer":"Luminance","explanation":"Three relate to repetition rate or perceived sound frequency. Luminance concerns light.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-67","version":2},{"kind":"choice","tag":"Life cycle","prompt":"Find the outsider.","options":["Larva","Egg","Pupa","Seed"],"answer":"Seed","explanation":"Egg, larva and pupa are stages in complete insect metamorphosis. A seed is a plant structure.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-60","version":2},{"kind":"choice","tag":"On the road","prompt":"Find the outsider.","options":["Tricycle","Monorail","Bicycle","Unicycle"],"answer":"Monorail","explanation":"Three names count wheels. A monorail runs on one rail or beam.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-65","version":2},{"kind":"choice","tag":"Frozen worlds","prompt":"Find the outsider.","options":["Earth","Neptune","Venus","Mercury"],"answer":"Neptune","explanation":"Three are terrestrial planets. Neptune is an ice giant.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-20","version":2}]'::jsonb);
INSERT INTO ledger_private.trivia_packs VALUES ('odd-one-out',13,2,'[{"kind":"choice","tag":"A game of words","prompt":"Find the outsider.","options":["Listen","Enlist","Silent","Insert"],"answer":"Insert","explanation":"Listen, silent and enlist are anagrams of the same six letters.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-43","version":2},{"kind":"choice","tag":"Behind the bar","prompt":"Find the outsider.","options":["Gin","Cider","Rum","Whisky"],"answer":"Cider","explanation":"Three are distilled spirits. Cider is fermented, rather than distilled.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-33","version":2},{"kind":"choice","tag":"Film credits","prompt":"Find the outsider.","options":["Director","Cinematographer","Editor","Cartographer"],"answer":"Cartographer","explanation":"Three are film production roles. A cartographer makes maps.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-90","version":2},{"kind":"choice","tag":"Kitchen chemistry","prompt":"Find the outsider.","options":["Yoghurt","Sourdough","Sauerkraut","Ice cubes"],"answer":"Ice cubes","explanation":"Three foods are made by fermentation. Freezing water makes ice.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-68","version":2},{"kind":"choice","tag":"The night sky","prompt":"Find the outsider.","options":["Ganymede","Europa","Titan","Venus"],"answer":"Venus","explanation":"Three are moons. Venus is a planet orbiting the Sun.","sources":["Original category puzzle; the explanation states the classification rule."],"id":"odd-one-out-v2-6","version":2}]'::jsonb);
