INSERT INTO ledger_private.trivia_packs VALUES ('before-or-after',0,2,'[{"kind":"timeline","prompt":"Put these moments in order.","cards":[{"id":"event-25","label":"Apple introduces the iPod","art":"music"},{"id":"event-0","label":"The first ARPANET message is sent","art":"computer"},{"id":"event-11","label":"The first Nintendo Switch launches","art":"game"},{"id":"event-5","label":"The first Kindle goes on sale","art":"book"},{"id":"event-34","label":"The first Apple computer is sold","art":"computer"}],"answer":["event-0","event-34","event-25","event-5","event-11"],"reveal":{"event-0":1969,"event-25":2001,"event-11":2017,"event-5":2007,"event-34":1976},"explanation":"1969 · The first ARPANET message is sent\n1976 · The first Apple computer is sold\n2001 · Apple introduces the iPod\n2007 · The first Kindle goes on sale\n2017 · The first Nintendo Switch launches","sources":["https://www.computerhistory.org/timeline/1969/","https://www.computerhistory.org/timeline/1976/","https://www.computerhistory.org/timeline/2001/","https://www.computerhistory.org/timeline/2007/","https://www.nintendo.com/en-gb/Hardware/Nintendo-Switch-Family/Nintendo-Switch/Nintendo-Switch-1148779.html"],"id":"before-or-after-v2-1","version":2}]'::jsonb);
