INSERT INTO ledger_private.trivia_packs VALUES ('how-much-ish',0,2,'[{"kind":"scale","prompt":"How big is a large male ostrich?","target":{"name":"A large male ostrich","shape":"ostrich","dimension":"height, up to"},"reference":{"name":"A city bus","shape":"bus","dimension":"length","measure":"12 m · length"},"bounds":[0.05,20],"answer":0.225,"explanation":"A large male ostrich: 2.7 m (height, up to). A city bus: 12 m. The target dimension is 0.23× the reference dimension.","sources":["https://animals.sandiegozoo.org/animals/ostrich","Defined reference dimension, shown before answering."],"id":"how-much-ish-v2-1","version":2},{"kind":"scale","prompt":"How big is an Antarctic blue whale?","target":{"name":"An Antarctic blue whale","shape":"whale","dimension":"length, up to"},"reference":{"name":"RMS Titanic","shape":"ship","dimension":"approximate length","measure":"269 m · approximate length"},"bounds":[0.05,20],"answer":0.12453531598513011,"explanation":"An Antarctic blue whale: 33.5 m (length, up to). RMS Titanic: 269 m. The target dimension is 0.12× the reference dimension.","sources":["https://www.fisheries.noaa.gov/species/blue-whale","https://www.ireland.com/en/magazine/long-reads/belfasts-titanic-legacy/"],"id":"how-much-ish-v2-2","version":2},{"kind":"scale","prompt":"How big is Saturn V with Apollo?","target":{"name":"Saturn V with Apollo","shape":"rocket","dimension":"height"},"reference":{"name":"A city bus","shape":"bus","dimension":"length","measure":"12 m · length"},"bounds":[0.05,20],"answer":9.25,"explanation":"Saturn V with Apollo: 111 m (height). A city bus: 12 m. The target dimension is 9.25× the reference dimension.","sources":["https://www.nasa.gov/learning-resources/for-kids-and-students/what-was-the-saturn-v-grades-5-8/","Defined reference dimension, shown before answering."],"id":"how-much-ish-v2-3","version":2},{"kind":"scale","prompt":"How big is Elizabeth Tower?","target":{"name":"Elizabeth Tower","shape":"clocktower","dimension":"approximate height"},"reference":{"name":"Boeing 737-800","shape":"plane","dimension":"nose-to-tail length","measure":"39.5 m · nose-to-tail length"},"bounds":[0.05,20],"answer":2.430379746835443,"explanation":"Elizabeth Tower: 96 m (approximate height). Boeing 737-800: 39.5 m. The target dimension is 2.43× the reference dimension.","sources":["https://www.parliament.uk/about/living-heritage/building/palace/big-ben/facts-figures/","https://www.boeing.com/commercial/737ng"],"id":"how-much-ish-v2-4","version":2},{"kind":"scale","prompt":"How big is a large male giraffe?","target":{"name":"A large male giraffe","shape":"giraffe","dimension":"height, up to"},"reference":{"name":"A large male ostrich","shape":"ostrich","dimension":"height, up to","measure":"2.7 m · height, up to"},"bounds":[0.05,20],"answer":2.0370370370370368,"explanation":"A large male giraffe: 5.5 m (height, up to). A large male ostrich: 2.7 m. The target dimension is 2.04× the reference dimension.","sources":["https://animals.sandiegozoo.org/animals/giraffe","https://animals.sandiegozoo.org/animals/ostrich"],"id":"how-much-ish-v2-5","version":2}]'::jsonb);
INSERT INTO ledger_private.trivia_packs VALUES ('how-much-ish',1,2,'[{"kind":"scale","prompt":"How big is Eiffel Tower, with antennas?","target":{"name":"Eiffel Tower, with antennas","shape":"tower","dimension":"height, 2026 reference"},"reference":{"name":"Space Shuttle orbiter","shape":"shuttle","dimension":"nose-to-tail length","measure":"37.24 m · nose-to-tail length"},"bounds":[0.05,20],"answer":8.861439312567132,"explanation":"Eiffel Tower, with antennas: 330 m (height, 2026 reference). Space Shuttle orbiter: 37.24 m. The target dimension is 8.86× the reference dimension.","sources":["https://www.toureiffel.paris/en/the-monument/key-figures","https://ntrs.nasa.gov/api/citations/19940023701/downloads/19940023701.pdf"],"id":"how-much-ish-v2-6","version":2},{"kind":"scale","prompt":"How big is Statue of Liberty, ground to torch?","target":{"name":"Statue of Liberty, ground to torch","shape":"statue-base","dimension":"height"},"reference":{"name":"Boeing 747-8","shape":"plane","dimension":"nose-to-tail length","measure":"76.3 m · nose-to-tail length"},"bounds":[0.05,20],"answer":1.2187418086500654,"explanation":"Statue of Liberty, ground to torch: 92.99 m (height). Boeing 747-8: 76.3 m. The target dimension is 1.22× the reference dimension.","sources":["https://www.nps.gov/stli/learn/historyculture/statue-statistics.htm","https://www.lufthansagroup.com/en/company/fleet/lufthansa-and-regional-partners/boeing-747-8.html"],"id":"how-much-ish-v2-7","version":2},{"kind":"scale","prompt":"How big is RMS Titanic?","target":{"name":"RMS Titanic","shape":"ship","dimension":"approximate length"},"reference":{"name":"Boeing 747-8","shape":"plane","dimension":"nose-to-tail length","measure":"76.3 m · nose-to-tail length"},"bounds":[0.05,20],"answer":3.525557011795544,"explanation":"RMS Titanic: 269 m (approximate length). Boeing 747-8: 76.3 m. The target dimension is 3.53× the reference dimension.","sources":["https://www.ireland.com/en/magazine/long-reads/belfasts-titanic-legacy/","https://www.lufthansagroup.com/en/company/fleet/lufthansa-and-regional-partners/boeing-747-8.html"],"id":"how-much-ish-v2-8","version":2},{"kind":"scale","prompt":"How big is Space Shuttle orbiter?","target":{"name":"Space Shuttle orbiter","shape":"shuttle","dimension":"nose-to-tail length"},"reference":{"name":"A large male giraffe","shape":"giraffe","dimension":"height, up to","measure":"5.5 m · height, up to"},"bounds":[0.05,20],"answer":6.770909090909091,"explanation":"Space Shuttle orbiter: 37.24 m (nose-to-tail length). A large male giraffe: 5.5 m. The target dimension is 6.77× the reference dimension.","sources":["https://ntrs.nasa.gov/api/citations/19940023701/downloads/19940023701.pdf","https://animals.sandiegozoo.org/animals/giraffe"],"id":"how-much-ish-v2-9","version":2},{"kind":"scale","prompt":"How big is SUE the T. rex?","target":{"name":"SUE the T. rex","shape":"trex","dimension":"approximate length"},"reference":{"name":"A large male giraffe","shape":"giraffe","dimension":"height, up to","measure":"5.5 m · height, up to"},"bounds":[0.05,20],"answer":2.2181818181818183,"explanation":"SUE the T. rex: 12.2 m (approximate length). A large male giraffe: 5.5 m. The target dimension is 2.22× the reference dimension.","sources":["https://www.fieldmuseum.org/blog/sue-t-rex","https://animals.sandiegozoo.org/animals/giraffe"],"id":"how-much-ish-v2-10","version":2}]'::jsonb);
